#!/bin/bash
pkill -f "s2_feeds.py"; sleep 1
echo  | base64 -d > /workspace/nox/tools/s2_feeds.py
cd /workspace/nox/tools; timeout 200 python3 s2_feeds.py music 2>&1 | tail -3
(nohup setsid python3 /workspace/nox/tools/s2_feeds.py loop >> /workspace/nox/svc/logs/s2_feeds.log 2>&1 < /dev/null &)
ls -la /workspace/nox/web/site/data/music_catalog.json
